ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  "order": {
    "totals": {
      "subtotal": "50",
      "total": "50"
    },
    "billingInfo": payload.order.billingInfo, 
    "shippingInfo": {
      "shipmentDetails": {
        "address": {
          "email": payload.order.shippingInfo.shipmentDetails.address.email, 
          "fullName": {  
            "firstName": payload.order.shippingInfo.shipmentDetails.address.fullName.firstName,
            "lastName": payload.order.shippingInfo.shipmentDetails.address.fullName.lastName
          },
          "country": payload.order.shippingInfo.shipmentDetails.address.country,
          "city": payload.order.shippingInfo.shipmentDetails.address.city,
          "phone": payload.order.shippingInfo.shipmentDetails.address.phone
        },
        "priceData": {
          "price": "50", 
          "taxIncludedInPrice": false
        }
      }
    },
    "paymentStatus": "NOT_PAID",
    "lineItems": payload.order.lineItems map (item) -> {
      "quantity": item.quantity,
      "name": item.name,
      "priceData": {
        "price": "50"
      }
    },
    "channelInfo": {
      "type": "WEB"
    }
  }
}
